55	        ret.name = "Median filter";
56	        ret.explanationWidget = Math::MedianFilter::createExplanationWidget();
57	        break;
58	    case Type::TDR:
59	        ret.name = "TDR";
60	        ret.explanationWidget = Math::TDR::createExplanationWidget();
61	        break;
62	    case Type::DFT:
63	        ret.name = "DFT";
64	        ret.explanationWidget = Math::DFT::createExplanationWidget();
65	        break;
66	    case Type::Expression:
67	        ret.name = "Custom Expression";
68	        ret.explanationWidget = Math::Expression::createExplanationWidget();
69	        break;
70	    case Type::TimeGate:
71	        ret.name = "Time Gate";
72	        ret.explanationWidget = Math::TimeGate::createExplanationWidget();
73	        break;
74	    case Type::TimeDomainGating: {
75	        ret.name = "Time Domain Gating";
76	        ret.explanationWidget = new QWidget();
77	        auto ui = new Ui::TimeDomainGatingExplanationWidget;
78	        ui->setupUi(ret.explanationWidget);
79	        connect(ret.explanationWidget, &QWidget::destroyed, [=](){
80	            delete ui;
81	        });
82	    }
83	        break;
84	    default:
85	        break;
86	    }
87	    return ret;
88	}
89	
90	TraceMath::Data TraceMath::getSample(unsigned int index)
91	{
92	    TraceMath::Data d;
93	    dataMutex.lock();
94	    if(index < data.size()) {
95	        d = data[index];
96	    }
97	    dataMutex.unlock();
98	    return d;
99	}
100	
101	double TraceMath::getStepResponse(unsigned int index)
102	{
103	    if(stepResponse.size() > index) {
104	        return stepResponse[index];
105	    } else {
106	        return std::numeric_limits<double>::quiet_NaN();
107	    }
108	}
109	
110	double TraceMath::getInterpolatedStepResponse(double x)
111	{
112	    QMutexLocker locker(&dataMutex);
113	    if(stepResponse.size() != data.size()) {
114	        // make sure all the step response data is available
115	        return std::numeric_limits<double>::quiet_NaN();
116	    }
117	
118	    double ret = std::numeric_limits<double>::quiet_NaN();
119	
120	    if(data.size() == 0 || x < data.front().x || x > data.back().x) {
121	        ret = std::numeric_limits<double>::quiet_NaN();
122	    } else {
123	        auto it = lower_bound(data.begin(), data.end(), x, [](const Data &lhs, const double x) -> bool {
124	            return lhs.x < x;
125	        });
126	        if(it->x == x || it == data.begin()) {
127	            ret = stepResponse[it - data.begin()];
128	        } else {
129	            // no exact match, needs to interpolate
130	            unsigned int highIndex = it - data.begin();
131	            unsigned int lowIndex = highIndex - 1;
132	            auto high = *it;
133	            it--;
134	            auto low = *it;
135	            double alpha = (x - low.x) / (high.x - low.x);
136	            ret = stepResponse[lowIndex] * (1 - alpha) + stepResponse[highIndex] * alpha;
137	        }
138	    }
139	    return ret;
140	}
141	
142	TraceMath::Data TraceMath::getInterpolatedSample(double x)
143	{
144	    Data ret;
145	    QMutexLocker locker(&dataMutex);
146	    if(data.size() == 0 || x < data.front().x || x > data.back().x) {
147	        ret.y = std::numeric_limits<std::complex<double>>::quiet_NaN();
148	        ret.x = std::numeric_limits<double>::quiet_NaN();
149	    } else {
150	        auto it = lower_bound(data.begin(), data.end(), x, [](const Data &lhs, const double x) -> bool {
151	            return lhs.x < x;
152	        });
153	        if(it->x == x) {
154	            ret = *it;
155	        } else {
156	            // no exact match, needs to interpolate
157	            auto high = *it;
158	            it--;
159	            auto low = *it;
160	            double alpha = (x - low.x) / (high.x - low.x);
161	            ret.y = low.y * (1 - alpha) + high.y * alpha;
162	            ret.x = x;
163	        }
164	    }
165	    return ret;
166	}
167	
168	unsigned int TraceMath::numSamples()
169	{
170	    dataMutex.lock();
171	    auto size = data.size();
172	    dataMutex.unlock();
173	    return size;
174	}
175	
176	QString TraceMath::dataTypeToString(TraceMath::DataType type)
177	{
178	    switch(type) {
179	    case DataType::Frequency:
180	        return "Frequency";
181	    case DataType::Power:
182	        return "Power";
183	    case DataType::Time:
184	        return "Time";
185	    case DataType::TimeZeroSpan:
186	        return "Time (Zero Span)";
187	    default:
188	        return "Invalid";
189	    }
190	}
191	
192	TraceMath::DataType TraceMath::dataTypeFromString(QString s)
193	{
194	    for(unsigned int i=0;i<(int) DataType::Invalid;i++) {
195	        if(s.compare(dataTypeToString((DataType) i), Qt::CaseInsensitive) == 0) {
196	            return (DataType) i;
197	        }
198	    }
199	    // not found
200	    return DataType::Invalid;
201	}
202	
203	void TraceMath::removeInput()
204	{
205	    if(input) {
206	        // disconnect everything from the input
207	        disconnect(input, nullptr, this, nullptr);
208	        input = nullptr;
209	        dataMutex.lock();
210	        data.clear();
211	        dataMutex.unlock();
212	        dataType = DataType::Invalid;
213	        emit outputTypeChanged(dataType);
214	    }
215	}
216	
217	void TraceMath::assignInput(TraceMath *input)
218	{
219	    Q_ASSERT(input != nullptr);
220	    if(input != this->input) {
221	        removeInput();
222	        this->input = input;
223	        connect(input, &TraceMath::outputTypeChanged, this, &TraceMath::inputTypeChanged);
224	        inputTypeChanged(input->dataType);
225	    }
226	}
227	
228	void TraceMath::inputTypeChanged(TraceMath::DataType type)
229	{
230	    auto newType = outputType(type);
231	    dataType = newType;
232	    dataMutex.lock();
233	    data.clear();
234	    dataMutex.unlock();
235	    if(dataType == DataType::Invalid) {
236	        error("Invalid input data");
237	        disconnect(input, &TraceMath::outputSamplesChanged, this, &TraceMath::inputSamplesChanged);
238	        updateStepResponse(false);
239	    } else {
240	        connect(input, &TraceMath::outputSamplesChanged, this, &TraceMath::inputSamplesChanged, Qt::UniqueConnection);
241	        input->dataMutex.lock();
242	        auto inputSize = input->data.size();
243	        input->dataMutex.unlock();
244	        inputSamplesChanged(0, inputSize);
245	    }
246	    emit outputTypeChanged(dataType);
247	}
248	
249	void TraceMath::warning(QString warn)
250	{
251	    statusString = warn;
252	    status = Status::Warning;
253	    emit statusChanged();
254	}
255	
256	void TraceMath::error(QString err)
257	{
258	    statusString = err;
259	    status = Status::Error;
260	    emit statusChanged();
261	}
262	
263	void TraceMath::success()
264	{
265	    if(status != Status::Ok) {
266	        status = Status::Ok;
267	        emit statusChanged();
268	    }
269	}
270	
271	QMutex& TraceMath::mutex()
272	{
273	    return dataMutex;
274	}
275	
276	std::complex<double> TraceMath::interpolatedSample(const std::vector<Data> &data, double x)
277	{
278	    if(data.empty() || x < data.front().x || x > data.back().x) {
279	        return std::numeric_limits<std::complex<double>>::quiet_NaN();
280	    }
281	
282	    auto it = lower_bound(data.begin(), data.end(), x, [](const TraceMath::Data &lhs, const double x) -> bool {
283	        return lhs.x < x;
284	    });
285	    if(it == data.end()) {
286	        return std::numeric_limits<std::complex<double>>::quiet_NaN();
287	    }
288	    if(it->x == x || it == data.begin()) {
289	        return it->y;
290	    }
291	
292	    auto high = *it;
293	    it--;
294	    auto low = *it;
295	    double alpha = (x - low.x) / (high.x - low.x);
296	    return low.y * (1 - alpha) + high.y * alpha;
297	}
298	
299	void TraceMath::updateStepResponse(bool valid)
300	{
301	    QMutexLocker locker(&dataMutex);
302	    if(valid) {
303	        stepResponse.resize(data.size());
304	        double accumulate = 0.0;
305	        for(unsigned int i=0;i<data.size();i++) {
306	            accumulate += data[i].y.real();
307	            stepResponse[i] = accumulate;
308	        }
309	    } else {
310	        stepResponse.clear();
311	    }
312	}
313	
314	TraceMath *TraceMath::getInput() const
315	{
316	    return input;
317	}
318	
319	QString TraceMath::getStatusDescription() const
320	{
321	    return statusString;
322	}
323	
324	Trace *TraceMath::root()
325	{
326	    auto root = this;
327	    while(root->input) {
328	        root = root->input;
329	    }
330	    return static_cast<Trace*>(root);
331	}
332	
333	TraceMath::Status TraceMath::getStatus() const
334	{
335	    return status;
336	}
337	
338	TraceMath::DataType TraceMath::getDataType() const
339	{
340	    return dataType;
341	}
342	
343	std::vector<TraceMath::Data> TraceMath::getData()
344	{
345	    dataMutex.lock();
346	    auto ret = data;
347	    dataMutex.unlock();
348	    return ret;
349	}
