351	double TraceMath::minX()
352	{
353	    double ret;
354	    dataMutex.lock();
355	    if(data.size() > 0) {
356	        ret = data.front().x;
357	    } else {
358	        ret = std::numeric_limits<double>::max();
359	    }
360	    dataMutex.unlock();
361	    return ret;
362	}
363	
364	double TraceMath::maxX()
365	{
366	    double ret;
367	    dataMutex.lock();
368	    if(data.size() > 0) {
369	        ret = data.back().x;
370	    } else {
371	        ret = std::numeric_limits<double>::min();
372	    }
373	    dataMutex.unlock();
374	    return ret;
375	}
