    Q_UNUSED(end)
    if(data.size() != inputData.size()) {
        dataMutex.lock();
        data.resize(inputData.size());
        dataMutex.unlock();
    }
    if(data.size() > 0) {
        if(end > inputData.size()) {
            end = inputData.size();
